/** @description Owns the private server-to-server greeting call and response validation. */

import { err, isErr, ok, tryAsync } from '@tenets/result';
import type { Result } from '@tenets/result';

/** @description Recoverable reasons a greeting could not be fetched from the API service. */
export interface GreetingServiceError {
	readonly code: 'EMPTY_NAME' | 'UPSTREAM_FAILURE' | 'INVALID_UPSTREAM_RESPONSE';
	readonly message: string;
}

function readMessage(value: unknown): string | undefined {
	if (typeof value !== 'object' || value === null || !('message' in value)) {
		return undefined;
	}

	const message = value.message;
	return typeof message === 'string' ? message : undefined;
}

function readEmptyNameMessage(value: unknown): string | undefined {
	if (typeof value !== 'object' || value === null || !('error' in value)) {
		return undefined;
	}

	const error = value.error;
	if (typeof error !== 'object' || error === null || !('code' in error) || !('message' in error)) {
		return undefined;
	}

	return error.code === 'EMPTY_NAME' && typeof error.message === 'string'
		? error.message
		: undefined;
}

async function readJsonBody(response: Response): Promise<unknown> {
	const body = await tryAsync(
		() => response.json() as Promise<unknown>,
		() => undefined,
	);
	return isErr(body) ? undefined : body.value;
}

/** @description Calls the bound API service and translates network/protocol failures once. */
export async function fetchGreeting({
	apiUrl,
	fetcher = fetch,
	name,
}: {
	readonly apiUrl: URL;
	readonly fetcher?: typeof fetch;
	readonly name: string;
}): Promise<Result<string, GreetingServiceError>> {
	const endpoint = new URL('/api/greet', apiUrl);
	endpoint.searchParams.set('name', name);

	const response = await tryAsync(
		() => fetcher(endpoint, { cache: 'no-store' }),
		(): GreetingServiceError => ({
			code: 'UPSTREAM_FAILURE',
			message: 'The greeting service is unavailable.',
		}),
	);
	if (isErr(response)) {
		return response;
	}

	if (!response.value.ok) {
		const emptyNameMessage =
			response.value.status === 400
				? readEmptyNameMessage(await readJsonBody(response.value))
				: undefined;

		if (emptyNameMessage !== undefined) {
			return err({ code: 'EMPTY_NAME', message: emptyNameMessage });
		}

		return err({
			code: 'UPSTREAM_FAILURE',
			message: 'The greeting service rejected the request.',
		});
	}

	const message = readMessage(await readJsonBody(response.value));

	if (message === undefined) {
		return err({
			code: 'INVALID_UPSTREAM_RESPONSE',
			message: 'The greeting service returned an invalid response.',
		});
	}

	return ok(message);
}

