/** @description Proves private service URL construction and response validation. */

import { err, ok } from '@tenets/result';
import { describe, expect, it, vi } from 'vitest';

import { fetchGreeting } from './api-client';

describe('fetchGreeting', () => {
	it('calls the deployment-aware API binding', async () => {
		const fetcher = vi
			.fn<typeof fetch>()
			.mockResolvedValue(Response.json({ message: 'Hello, Ada!' }));

		await expect(
			fetchGreeting({
				apiUrl: new URL('https://private-service.vercel.sh'),
				fetcher,
				name: 'Ada',
			}),
		).resolves.toEqual(ok('Hello, Ada!'));

		expect(fetcher).toHaveBeenCalledWith(
			new URL('https://private-service.vercel.sh/api/greet?name=Ada'),
			{ cache: 'no-store' },
		);
	});

	it('passes the typed empty-name failure through as a recoverable client error', async () => {
		const fetcher = vi
			.fn<typeof fetch>()
			.mockResolvedValue(
				Response.json(
					{ error: { code: 'EMPTY_NAME', message: 'A non-empty name is required.' } },
					{ status: 400 },
				),
			);

		await expect(
			fetchGreeting({ apiUrl: new URL('https://service.test'), fetcher, name: '   ' }),
		).resolves.toEqual(err({ code: 'EMPTY_NAME', message: 'A non-empty name is required.' }));
	});

	it('translates a rejected fetch into an upstream failure', async () => {
		const fetcher = vi.fn<typeof fetch>().mockRejectedValue(new Error('connection refused'));

		await expect(
			fetchGreeting({ apiUrl: new URL('https://service.test'), fetcher, name: 'Ada' }),
		).resolves.toEqual(
			err({ code: 'UPSTREAM_FAILURE', message: 'The greeting service is unavailable.' }),
		);
	});

	it('translates a successful response without a JSON body', async () => {
		const fetcher = vi.fn<typeof fetch>().mockResolvedValue(new Response('not json'));

		await expect(
			fetchGreeting({ apiUrl: new URL('https://service.test'), fetcher, name: 'Ada' }),
		).resolves.toEqual(
			err({
				code: 'INVALID_UPSTREAM_RESPONSE',
				message: 'The greeting service returned an invalid response.',
			}),
		);
	});

	it('translates a malformed upstream response', async () => {
		const fetcher = vi.fn<typeof fetch>().mockResolvedValue(Response.json({ greeting: 'Hello' }));

		await expect(
			fetchGreeting({ apiUrl: new URL('https://service.test'), fetcher, name: 'Ada' }),
		).resolves.toEqual(
			err({
				code: 'INVALID_UPSTREAM_RESPONSE',
				message: 'The greeting service returned an invalid response.',
			}),
		);
	});
});
